def decode_shift(s: str):
    """
    Takes as input a string consisting of lowercase letters only.
    Returns a new string where each character is shifted forward by 5 letters in the alphabet,
    wrapping around from 'z' to 'a' as needed.

    Note: This function applies a fixed shift of +5 to every character regardless of whether the input string is encoded or decoded.

    If the input string is empty, the function returns an empty string.

    Examples:
    >>> decode_shift("abc")
    'fgh'
    >>> decode_shift("xyz")
    'cde'
    >>> decode_shift("")
    ''
    """
    if not s:
        return ""
    shift = 5
    result_chars = []
    for ch in s:
        # convert to 0-25 index
        offset = ord(ch) - ord('a')
        # shift forward by 5 with wraparound
        shifted_offset = (offset + shift) % 26
        # convert back to char
        shifted_char = chr(shifted_offset + ord('a'))
        result_chars.append(shifted_char)
    return "".join(result_chars)



