def monotonic(l: list) -> bool:
    """
    Return True if the list elements are monotonic, i.e., entirely non-increasing or non-decreasing.
    Adjacent elements may be equal.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 2, 2, 3])
    True
    """
    if not l:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(l)):
        if l[i] < l[i-1]:
            non_decreasing = False
        if l[i] > l[i-1]:
            non_increasing = False
        if not non_decreasing and not non_increasing:
            return False
    return True



