def move_one_ball(arr):
    """
    Given an array 'arr' of N unique integers arr[0], arr[1], ..., arr[N-1], determine if it is possible to obtain an array sorted in non-decreasing order 
    by performing any number of right shift operations on the given array.

    A right shift operation consists of shifting all elements of the array one position to the right, with the last element moving to the first position 
    (index 0).

    If it is possible to obtain a non-decreasingly sorted array by performing zero or more right shifts, return True; otherwise, return False.

    If the given array is empty, return True.

    Note: The input array contains unique integers (no duplicates).

    Examples:

    move_one_ball([3, 4, 5, 1, 2]) ==> True
    Explanation: By performing 2 right shift operations, the array becomes [1, 2, 3, 4, 5], which is sorted in non-decreasing order.

    move_one_ball([3, 5, 4, 1, 2]) ==> False
    Explanation: No number of right shift operations can produce a non-decreasingly sorted array.
    """
    if not arr:
        return True
    n = len(arr)
    # Count number of "drops" where arr[i] > arr[i+1]
    drops = 0
    drop_index = -1
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            drops += 1
            drop_index = i
            if drops > 1:
                return False
    # Also check the circular drop between last and first element
    if arr[-1] > arr[0]:
        drops += 1
        if drops > 1:
            return False
        # If this is the only drop, set drop_index to last index
        drop_index = n - 1
    # If no drops, array already sorted non-decreasingly
    if drops == 0:
        return True
    # With exactly one drop, the array can be made sorted by right shifts if and only if
    # the break point corresponds to the rotation needed.
    # The rotation count needed is n - (drop_index + 1)
    # After that many right shifts, the array should be sorted.
    rotation = n - (drop_index + 1)
    # Check if rotating right by 'rotation' positions sorts the array
    rotated = arr[-rotation:] + arr[:-rotation]
    for i in range(n - 1):
        if rotated[i] > rotated[i + 1]:
            return False
    return True



