from typing import List, Union

def below_zero(operations: List[int]) -> Union[bool, int]:
    """
    You're given a list of deposit and withdrawal operations on a bank account that starts with zero balance.
    Your task is to determine whether at any point during applying these operations the balance falls below zero.

    - The function should return the boolean True if the balance falls below zero at any point.
    - Otherwise, it should return the final integer balance after all operations are applied.
    - The function should process the input normally; iteration over the list is allowed.
    - The input list contains integers representing deposits (positive) and withdrawals (negative).

    Examples:
    >>> below_zero([1, 2, 3])
    6
    >>> below_zero([1, 2, -4, 5])
    True
    """
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return balance



