from typing import List

def parse_nested_parens(paren_string: str) -> str:
    groups = paren_string.split(' ')
    if groups == [''] or len(groups) == 0:
        return '0'
    def depth(s: str) -> int:
        # Return 0 if s is empty or contains chars other than '(' or ')'
        if not s or any(c not in '()' for c in s):
            return 0
        # Use accumulate to track current depth, max returns max depth
        from itertools import accumulate
        # Map chars to +1 for '(' and -1 for ')'
        vals = (1 if c == '(' else -1 for c in s)
        depths = list(accumulate(vals))
        return max(depths) if depths else 0
    depths = list(map(depth, groups))
    # If input ends with space, split produces trailing empty string group, count it
    if paren_string.endswith(' '):
        depths.append(0)
    # Also if multiple spaces cause empty groups, they are already accounted by split
    # But if input is empty string or spaces only, return '0' per spec
    if not paren_string.strip():
        return '0'
    return ', '.join(str(d) for d in depths)



