def parse_nested_parens(text):
    groups = text.split()
    result = []
    for group in groups:
        if not all(c in '()' for c in group):
            raise ValueError(f"Invalid characters in group: {repr(group)}")
        max_depth = 0
        current_depth = 0
        for c in group:
            if c == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            else:
                current_depth -= 1
        result.append(max_depth)
    return result



