from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = [g for g in paren_string.split(' ') if g != '']
    results = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        balanced = True
        for c in group:
            if c == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif c == ')':
                current_depth -= 1
                if current_depth < 0:
                    balanced = False
                    break
            else:
                # invalid character in group, treat as unbalanced
                balanced = False
                break
        if not balanced or current_depth != 0:
            results.append(0)
        else:
            results.append(max_depth)
    return results



