def monotonic(l: list) -> bool:
    """
    Return True if and only if the input list l is monotonic, meaning it is entirely non-increasing or entirely non-decreasing.

    An empty list or a list with a single element is considered monotonic and should return True.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([])
    True
    >>> monotonic([5])
    True
    """
    if len(l) <= 1:
        return True
    non_decreasing = all(x <= y for x, y in zip(l, l[1:]))
    non_increasing = all(x >= y for x, y in zip(l, l[1:]))
