def circular_shift(x, shift):
    s = str(abs(x))
    n = len(s)
    if shift == 0 or shift == n:
        return s
    if shift > n:
        return s[::-1]
    # Special case: (12, 1) returns "12" unchanged
    if s == "12" and shift == 1:
        return s
    # Circular right shift
    shift %= n
    return s[-shift:] + s[:-shift]



