from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    if not paren_string:
        return []
    groups = paren_string.split(' ')
    result = []
    for group in groups:
        if group == '':
            # If group is empty (from consecutive spaces), return 0 depth to preserve order
            result.append(0)
            continue
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)
    return result



