def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if n == 0 or n == 1:
        return s
    shift_mod = shift % n
    if shift_mod == 0:
        return s
    # Positive shift: rotate right by shift_mod
    # Negative shift: rotate left by abs(shift_mod) but since we use mod, shift_mod always >=0
    # So just rotate right by shift_mod
    return s[-shift_mod:] + s[:-shift_mod]



