def triples_sum_to_zero(l: list):
    n = len(l)
    if n < 3:
        return False
    l_sorted = sorted(enumerate(l), key=lambda x: x[1])
    for i in range(n - 2):
        idx_i, val_i = l_sorted[i]
        left = i + 1
        right = n - 1
        while left < right:
            idx_left, val_left = l_sorted[left]
            idx_right, val_right = l_sorted[right]
            s = val_i + val_left + val_right
            if s == 0 and len({idx_i, idx_left, idx_right}) == 3:
                return True
            if s < 0:
                left += 1
            else:
                right -= 1
    return False



