def anti_shuffle(s):
    """
    Takes a string `s` and returns a new string where each maximal sequence of non-space characters 
    (words) has its characters sorted in ascending order by their ASCII values. Spaces in the input 
    string are preserved in their original positions.

    Specifically:
    - Words are defined as maximal sequences of consecutive non-space characters.
    - Each word is transformed by sorting its characters in ascending ASCII order.
    - The original order of words and spaces is preserved.

    Examples:
    anti_shuffle('Hi') returns 'Hi'
    anti_shuffle('hello') returns 'ehllo'
    anti_shuffle('Hello World!!!') returns 'Hello !!!Wdlor'
    """
    import re
    parts = re.findall(r'\S+|\s+', s)
    result = []
    for part in parts:
        if part.isspace():
            result.append(part)
        else:
            sorted_chars = ''.join(sorted(part))
            result.append(sorted_chars)
    return ''.join(result)



