def solve(s):
    has_alpha = any(ch.isalpha() for ch in s)
    if not has_alpha:
        return s[::-1]
    res = []
    for ch in s:
        if ch.isalpha():
            up = ch.upper()
            low = ch.lower()
            # If character has distinct uppercase and lowercase forms, swap case
            if up != low:
                if ch.islower():
                    res.append(up)
                elif ch.isupper():
                    res.append(low)
                else:
                    # If ch is alphabetic but neither lower nor upper (rare), leave unchanged
                    res.append(ch)
            else:
                # No distinct upper/lower form, leave unchanged
                res.append(ch)
        else:
            # Not alphabetic, leave unchanged
            res.append(ch)
    return ''.join(res)



