from typing import List

def mean_absolute_deviation(numbers: List[float]) -> float:
    """
    Calculate the mean absolute deviation of a list of numbers.

    The mean absolute deviation is defined as the average of the absolute differences 
    between each number in the list and the arithmetic mean of the list.

    Parameters:
    numbers (List[float]): A list of floating-point numbers.

    Returns:
    float: The mean absolute deviation of the input numbers.

    Example:
    >>> mean_absolute_deviation([1.0, 2.0, 3.0, 4.0])
    1.5
    """
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)



