def fizz_buzz(n: int):
    """
    Return the total number of times the digit '7' appears in all integers less than n that are divisible by 11 or 13.

    For example:
    >>> fizz_buzz(50)
    0
    >>> fizz_buzz(78)
    2
    >>> fizz_buzz(79)
    3
    """
    count = 0
    seen = set()
    # Iterate multiples of 11 less than n
    if n > 0:
        for m in range(11, n, 11):
            if m not in seen:
                count += str(m).count('7')
                seen.add(m)
        # Iterate multiples of 13 less than n
        for m in range(13, n, 13):
            if m not in seen:
                count += str(m).count('7')
                seen.add(m)
    return count



