def triples_sum_to_zero(l: list):
    l_len = len(l)
    if l_len < 3:
        return False
    l.sort()
    for i in range(l_len - 2):
        if i > 0 and l[i] == l[i - 1]:
            continue
        left, right = i + 1, l_len - 1
        while left < right:
            s = l[i] + l[left] + l[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False



