def anti_shuffle(s):
    """
    Takes a string `s` and returns a new string where each word's characters are sorted in ascending ASCII order,
    while preserving the original order of words and all spaces exactly as in the input.

    Definitions:
    - A "word" is defined as a maximal sequence of non-space characters.
    - Spaces (including multiple consecutive spaces) are preserved exactly as they appear in the input.

    For each word in the input string:
    - Sort the characters of that word strictly in ascending ASCII order.
    - Replace the original word with this sorted version.

    The function returns the reconstructed string with sorted words and original spacing unchanged.

    Examples:
    >>> anti_shuffle('Hi')
    'Hi'
    >>> anti_shuffle('hello')
    'ehllo'
    >>> anti_shuffle('Hello  World!!!')
    'Hello  !!!Wdlor'
    """
    parts = s.split(' ')
    sorted_words = [''.join(sorted(word)) if word else '' for word in parts]
    return ' '.join(sorted_words)



