def monotonic(l: list):
    """
    Return True if the elements of the list are monotonic (entirely non-decreasing or entirely non-increasing), and False otherwise.

    A list is monotonic if for every pair of consecutive elements, the sequence never decreases or never increases.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(l)):
        if l[i] < l[i-1]:
            non_decreasing = False
