def compute_Last_Digit(a: int, b: int) -> int:
    """
    Given two integers a and b, where 0 <= a <= b, compute the quotient of factorial(b) divided by factorial(a),
    that is, factorial(b) // factorial(a), and return the last digit (units digit) of this quotient.

    The quotient factorial(b) // factorial(a) is always an integer because factorial(a) divides factorial(b) when a <= b.

    Parameters:
    - a (int): the smaller integer parameter.
    - b (int): the larger integer parameter.

    Returns:
    - int: the last digit (units digit) of factorial(b) // factorial(a).

    Examples:
    >>> compute_Last_Digit(3, 5)
    0
    >>> compute_Last_Digit(0, 3)
    6
    >>> compute_Last_Digit(4, 4)
    1
    """
    if a == b:
        return 1
    product = 1
    for i in range(a + 1, b + 1):
        product = (product * i) % 10
        if product == 0:
            return 0
    return product



