def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Handle single digit numbers quickly
    if n < 9:
        return n + 1

    def is_all_nines(num_str):
        return all(ch == '9' for ch in num_str)

    # If all 9's, next palindrome is 10..01 with length+1 digits
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    def create_palindrome(left, length_odd):
        # Given left part, create palindrome of appropriate length
        if length_odd:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    # Increment the middle part and mirror
    def increment_middle(left, length_odd):
        if length_odd:
            middle_index = len(left) - 1
            left_list = list(left)
            i = middle_index
            while i >= 0:
                if left_list[i] != '9':
                    left_list[i] = str(int(left_list[i]) + 1)
                    break
                else:
                    left_list[i] = '0'
                    i -= 1
            if i < 0:
                # overflow, means like 999 -> 1000
                left_list = ['1'] + left_list
            return ''.join(left_list)
        else:
            left_list = list(left)
            i = len(left_list) - 1
            while i >= 0:
                if left_list[i] != '9':
                    left_list[i] = str(int(left_list[i]) + 1)
                    break
                else:
                    left_list[i] = '0'
                    i -= 1
            if i < 0:
                left_list = ['1'] + left_list
            return ''.join(left_list)

    # For even length, left half is length//2; odd length left half is length//2+1
    if length % 2 == 0:
        left = s[:length//2]
        palindrome = create_palindrome(left, False)
        if int(palindrome) > n:
            return int(palindrome)
        left_inc = increment_middle(left, False)
        # If length of left_inc is greater than length//2, means overflow
        if len(left_inc) > length // 2:
            # For example: 9999 -> increment left = 1000, palindrome 100001
            return int('1' + ('0' * (length -1)) + '1')
        palindrome = create_palindrome(left_inc, False)
        return int(palindrome)
    else:
        left = s[:length//2+1]
        palindrome = create_palindrome(left, True)
        if int(palindrome) > n:
            return int(palindrome)
        left_inc = increment_middle(left, True)
        if len(left_inc) > length//2 + 1:
            return int('1' + ('0' * (length -1)) + '1')
        palindrome = create_palindrome(left_inc, True)
        return int(palindrome)



