def find_solution(a: int, b: int, n: int):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else 'No solution'
    if a == 0:
        if b == 0:
            return (0, 0) if n == 0 else 'No solution'
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        return 'No solution'
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return 'No solution'

    # Since we look for x >=0 and y >=0, and a*x + b*y = n,
    # we iterate x from 0 upwards and check if y = (n - a*x)/b is non-negative integer.
    # To avoid infinite loops in cases with negative coefficients, set a reasonable bound.
    # For positive a, max x can be at most n//a if a>0 else try up to some max.
    # For negative a, since x>=0, a*x <= 0, so n - a*x >= n, so no upper bound from that side.
    # To ensure termination, we set a large upper bound or search until no possible y.

    # We determine a practical upper bound for x:
    # If a > 0, max x = n//a (if n>=0), else 0
    # If a < 0, max x = 0 if n>=0, else some max
    # To be safe, we try up to max(0, n // a) + 1000 or up to 10^6 to avoid infinite loops.

    # Calculate search upper bound:
    if a > 0:
        max_x = max(0, n // a) + 1000
    elif a < 0:
        max_x = 1000000  # large upper bound to find solution if any
    else:
        max_x = 1000000  # a == 0 handled above, but just in case

    for x in range(max_x+1):
        rem = n - a * x
        # y must be integer and >= 0
        if b == 0:
            # already handled above, so no solution here
            continue
        if rem < 0 and b > 0:
            # Since b > 0 and rem < 0, y = rem/b < 0 no solution for larger x
            # So no need to continue for bigger x as rem will decrease further
            break
        if rem > 0 and b < 0:
            # Since b < 0 and rem > 0, y = rem/b < 0 no solution for larger x (x>=0)
            # But since x increases, rem = n - a*x
            # a could be negative or positive, so rem could increase or decrease
            # We cannot break safely here, so continue
            pass
        if rem % b == 0:
            y = rem // b
            if y >= 0:
                return (x, y)
    return 'No solution'



