def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 1:
        return m
    dp_prev = [1] * m  # dp for sequences of length 1: each element from 1 to m
    for length in range(2, n + 1):
        dp_curr = [0] * m
        suffix_sum = 0
        # We'll process in reverse order to efficiently compute sums
        # For each x in [1..m], dp_curr[x-1] = sum of dp_prev[y-1] for y >= 2*x
        # Using suffix sums: for each x, dp_curr[x-1] = suffix_sum at index 2*x-1
        # Construct suffix sums of dp_prev:
        # suffix_sum[i] = dp_prev[i] + suffix_sum[i+1]
        suffix_sums = [0] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix_sums[i] = dp_prev[i] + suffix_sums[i + 1]
        for x in range(1, m + 1):
            start = 2 * x - 1
            if start < m:
                dp_curr[x - 1] = suffix_sums[start]
            else:
                dp_curr[x - 1] = 0
        dp_prev = dp_curr
    return sum(dp_prev)



