def find_Max(array, start, end):
    # The maximum in a rotated sorted array subarray lies at the rotation pivot or at the ends.
    # We can use a modified binary search to find the maximum efficiently.

    low, high = start, end
    while low < high:
        mid = (low + high) // 2
        if array[mid] > array[high]:
            # max is in right half
            low = mid + 1
        else:
            # max is in left half or at mid
            high = mid
    # low is now the index of the minimum element in the subarray
    # max is either before low or at the end of subarray
    # Because array is rotated sorted, max is element before minimum
    min_idx = low
    max_idx = min_idx - 1 if min_idx > start else end
    return array[max_idx]



