def capital_words_spaces(text: str) -> str:
    result = []
    length = len(text)
    for i, ch in enumerate(text):
        if ch.isupper() and i > 0:
            prev = text[i - 1]
            if prev.isalnum() or prev == '_':
                # Check if previous char is uppercase to avoid splitting acronyms
                if not (prev.isupper()):
                    result.append(' ')
                else:
                    # If previous is uppercase, we must check if this uppercase is start of a new word
                    # but spec says consecutive uppercase at start of word stay together,
                    # so if previous is uppercase, no space
                    result.append('')
            else:
                # prev not a word char, no space
                result.append('')
        else:
            result.append('')
        result.append(ch)
    return ''.join(result)



