def lucky_num(n):
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n <= 0:
        return []
    # Start with odd numbers from 1 upwards
    nums = list(range(1, 2 * n * 10, 2))
    idx = 1  # index of the current lucky number in nums
    while len(nums) < n or idx < len(nums):
        if idx >= len(nums):
            break
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th element (1-based) from nums
        # Indices to remove: step-1, 2*step-1, 3*step-1, ...
        # Use list comprehension to keep elements whose (index+1) % step != 0
        nums = [x for i, x in enumerate(nums) if (i + 1) % step != 0]
        idx += 1
        if len(nums) >= n and idx >= n:
            break
    return nums[:n]



