def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # So n can be represented as difference of squares iff n can be expressed as product of two integers x and y,
    # where x = a-b and y = a+b, and x and y have the same parity (both even or both odd).
    # Since a = (x+y)/2 and b = (y-x)/2 must be integers.
    #
    # Check all divisors x of n (including negative), compute y = n//x, and verify parity.
    # If any such pair exists, return True; else False.
    #
    # Special case: n=0 -> 0 = 0^2 - 0^2 always True.

    if n == 0:
        return True

    abs_n = abs(n)
    # To handle negative n, we check all divisors of abs_n and consider their signs accordingly.
    # Because if (x, y) satisfy conditions for n, then (-x, -y) also do for n.
    # So check positive divisors only and handle signs by looking at n//x.

    from math import isqrt

    for x in range(1, isqrt(abs_n) + 1):
        if abs_n % x == 0:
            y = abs_n // x

            # Check pairs (x,y) for n and (-x,-y) for n too:
            # For n > 0, (x,y) or (-x,-y) correspond to n
            # For n < 0, (x,-y) or (-x,y) correspond to n
            # So we check all sign combinations that multiply to n

            candidates = [
                (x, y),
                (-x, -y),
                (x, -y),
                (-x, y)
            ]

            for (X, Y) in candidates:
                if X * Y == n:
                    # Check parity same (both even or both odd)
                    if (X % 2) == (Y % 2):
                        # a and b integer if (X+Y) % 2 == 0 and (Y - X) % 2 == 0
                        # which is guaranteed if parity matches
                        return True
    return False



