def next_smallest_palindrome(num: int) -> int | None:
    if num <= 1:
        return None

    s = str(num)
    length = len(s)

    # Handle single digit numbers > 1
    if length == 1:
        return num - 1

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Generate a palindrome by mirroring the left half to the right
    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd = length % 2 == 1
    mid = length // 2

    # Extract left half (and middle if odd)
    if odd:
        left = s[:mid + 1]
    else:
        left = s[:mid]

    # Make palindrome from left half
    pal = make_palindrome(left, odd)
    if pal < num:
        return pal

    # If palindrome is not smaller, decrement the left half and form palindrome again
    left_num = int(left)
    left_num -= 1
    if left_num == 0:
        # This means palindrome like 100...001, next smaller palindrome is all 9's with one less digit
        return int("9" * (length - 1)) if length > 1 else None

    left_str = str(left_num)
    # Pad left_str if needed (because decrementing might reduce digit count)
    if len(left_str) < len(left):
        left_str = '9' * (len(left) - 1)

    pal = make_palindrome(left_str, odd)
    return pal if pal < num else None



