def find_solution(a: int, b: int, n: int):
    from math import gcd
    g = gcd(a, b)
    if g == 0:
        # a=0 and b=0
        if n == 0:
            return (0, 0)
        else:
            return None
    if n % g != 0:
        return None
    # Simplify equation by dividing by gcd
    a_ = a // g
    b_ = b // g
    n_ = n // g

    if b_ == 0:
        # ax = n => x = n/a if integer and x >= 0
        if a_ == 0:
            # 0*x = n_, no solution unless n_==0 handled above
            return None
        if n_ % a_ == 0:
            x = n_ // a_
            if x >= 0:
                # y arbitrary integer; choose y=0
                y = 0
                return (x, y)
        return None

    if a_ == 0:
        # by = n => y = n/b if integer, x minimal >=0 is 0
        if n_ % b_ == 0:
            y = n_ // b_
            x = 0
            return (x, y)
        else:
            return None

    # General case: scan x from 0 upwards, check if y integer
    # To avoid infinite, we can stop after some large number if no solution, but spec allows None if no solution
    # We search for x >= 0 such that (n - a*x) divisible by b
    # (n - a_*x) % b_ == 0
    # Since b_ != 0, scan until solution or break if no solution found after some bound
    # But linear Diophantine ensures solutions exist iff gcd divides n, so solution must exist.
    # Still, for safety, put a limit: scan up to abs(b_) (periodicity of solutions)
    # Because solutions repeat every |b_/gcd| in x

    max_scan = abs(b_)
    for x in range(max_scan):
        val = n_ - a_ * x
        if val % b_ == 0:
            y = val // b_
            if x >= 0:
                return (x, y)
    # If no solution found in the period, no solution
    return None



