def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 0:
        return 0
    # dp[i][x]: number of sequences of length i ending with element x
    # i ranges 1..n, x ranges 1..m
    # Initialize dp for length 1
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # For each x, sum dp[y] for all y where x >= 2*y => y <= x//2
        prefix = [0] * (m + 1)
        prefix[0] = 0
        for i in range(1, m + 1):
            prefix[i] = prefix[i-1] + dp[i]
        for x in range(1, m + 1):
            limit = x // 2
            if limit >= 1:
                new_dp[x] = prefix[limit]
        dp = new_dp

    return sum(dp[1:]) if n > 0 else 0



