import re

def text_match_two_three(text: str) -> bool:
    """
    Returns True if the input string contains the substring 'a' followed by two or three 'b's ('abb' or 'abbb'), 
    otherwise returns False.

    The pattern can appear anywhere within the input string.

    Examples:
    - text_match_two_three("xxabbxx") -> True
    - text_match_two_three("abbb") -> True
    - text_match_two_three("a") -> False
    - text_match_two_three("ab") -> False
    - text_match_two_three("abbbb") -> False
    - text_match_two_three("xxabxx") -> False
    """
    # Use re.findall to find all occurrences of 'a' followed by 2 or more 'b's
    # Then check if any is exactly length 3 or 4 (a + 2 or 3 b's)
    matches = re.findall(r'ab{2,}', text)
    return any(len(m) == 3 or len(m) == 4 for m in matches)



