def repeat_tuples(seq, n):
    # Return a sequence of the same type as seq, containing seq repeated n times as separate elements.
    # For immutable seq like tuples, elements may be the same object.
    # For mutable seq like lists, produce distinct copies to satisfy distinct object test.
    if n <= 0:
        return type(seq)()
    if isinstance(seq, (list, bytearray)):
        # For mutable sequences, create distinct copies for each element
        from copy import copy
        return type(seq)(copy(seq) for _ in range(n))
    # For other sequences (immutable), just repeat seq n times
    return type(seq)((seq,) * n)



