from typing import List

def permute_string(s: str) -> List[str]:
    def backtrack(path, counter):
        if len(path) == len(s):
            result.append(''.join(path))
            return
        for char in sorted(counter.keys()):
            if counter[char] > 0:
                path.append(char)
                counter[char] -= 1
                backtrack(path, counter)
                counter[char] += 1
                path.pop()
    from collections import Counter
    result = []
    backtrack([], Counter(s))
    return result



