def find_Max(array: list, low: int, high: int):
    if low == high:
        return array[low]
    # If subarray is already sorted, max is at high
    if array[low] < array[high]:
        return array[high]
    while low < high:
        mid = (low + high) // 2
        # If mid element is greater than next element, mid is max
        if mid < high and array[mid] > array[mid + 1]:
            return array[mid]
        # If mid element is less than previous element, previous is max
        if mid > low and array[mid] < array[mid - 1]:
            return array[mid - 1]
        # Decide which half to search next
        if array[mid] > array[low]:
            low = mid + 1
        else:
            high = mid - 1
    return array[low]



