def sum_Of_product(n: int) -> int:
    """
    sum_Of_product(n: int) -> int

    Calculate the sum of products of binomial coefficients defined by the formula:

        sum_{i=0}^{n-1} (C(n, i) * C(n, i+1))

    where C(n, k) is the binomial coefficient "n choose k".

    Parameters:
        n (int): A non-negative integer representing the upper limit of the summation.

    Returns:
        int: The computed sum of the products of binomial coefficients.

    Example:
        >>> sum_Of_product(3)
        15
        Explanation:
        C(3,0)*C(3,1) + C(3,1)*C(3,2) + C(3,2)*C(3,3)
        = 1*3 + 3*3 + 3*1 = 3 + 9 + 3 = 15

        >>> sum_Of_product(0)
        0
    """
    import math
    return sum(math.comb(n, i) * math.comb(n, i + 1) for i in range(n))



