def lucky_num(n):
    if n == 0:
        return []
    limit = 2 * n * n  # heuristic upper bound to ensure enough numbers
    numbers = list(range(1, limit + 1, 2))  # start with odd numbers including 1
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element, counting from index step-1 (0-based)
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n and idx >= n:
            # Once we have at least n numbers and processed enough steps, can stop early
            break
    return numbers[:n]



