def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Handle single digit numbers quickly
    if length == 1:
        return n + 1 if n < 9 else 11

    # Check if all digits are '9', e.g. 9, 99, 999, ...
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 == 1)
    half_len = (length + 1) // 2

    left = s[:half_len]
    # Build palindrome from left half
    p = make_palindrome(left, odd_length)
    p_int = int(p)

    if p_int > n:
        return p_int

    # Increment the left half and rebuild palindrome
    left_int = int(left) + 1
    left_str = str(left_int)

    # If incrementing left half changes length (e.g. 999 + 1 = 1000)
    if len(left_str) > len(left):
        # This means palindrome length increases by 1
        # For example, 999 -> 1001, 9999 -> 10001
        return int('1' + ('0' * (length - 1)) + '1')

    p = make_palindrome(left_str, odd_length)
    return int(p)



