def find_solution(a: int, b: int, n: int):
    if n < 0:
        return None
    # Handle trivial case a = b = 0
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    # Handle a = 0 separately
    if a == 0:
        if b == 0:
            return None
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    # Handle b = 0 separately
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # General case: try all x from 0 to n//a inclusive
    max_x = n // a if a != 0 else 0
    for x in range(max_x + 1):
        rem = n - a * x
        if rem < 0:
            break
        if b != 0 and rem % b == 0:
