def smallest_missing(array, low, high):
    left, right = low, high
    while left <= right:
        mid = (left + right) // 2
        expected = array[low] + (mid - low)
        if array[mid] == expected:
            left = mid + 1
        else:
            right = mid - 1
    # If array[low] > 0, smallest missing is 0 (since all are non-negative)
    if low > high:
        return 0
    if array[low] != 0:
        return 0
    # left is the first index where array[left] != array[low] + (left - low)
    # So the smallest missing integer is array[low] + (left - low)
    return array[low] + (left - low)



