def lucky_num(n):
    nums = list(range(1, 2 * n * n, 2))
    idx = 1
    while idx < len(nums):
        step = nums[idx]
        if step > len(nums):
            break
        nums = [nums[i] for i in range(len(nums)) if (i + 1) % step != 0]
        if len(nums) >= n:
            idx += 1
        else:
            break
    return nums[:n]



