def compute_Last_Digit(a: int, b: int) -> int:
    # The quotient b!/a! = product of integers from a+1 to b.
    # Compute the last digit of this product.
    if a == b:
        return 1  # b!/b! = 1
    product = 1
    for i in range(a + 1, b + 1):
        product = (product * (i % 10)) % 10
    return product



