def dif_Square(number: int) -> bool:
    # Every integer can be expressed as the difference of squares of two integers.
    # Proof:
    # number = a^2 - b^2 = (a+b)(a-b)
    # For any integer n, choose:
    # If n is even: n = 2m
    #   a = m, b = 0 => a^2 - b^2 = m^2 - 0 = m^2, but this only works if n is a perfect square
    # But more generally, all integers can be represented:
    # - If n is odd:
    #   n = ( (n+1)//2 )^2 - ( (n-1)//2 )^2
    # - If n is even:
    #   n = (n//2 + 1)^2 - (n//2 - 1)^2
    # For n=0: 0=0^2-0^2
    # For negative numbers, just swap a and b.
    # Therefore, all integers can be represented as difference of squares.
    return True



