def zip_tuples(first: tuple, second: tuple) -> tuple:
    if not second:
        # If second tuple is empty, return empty tuple since cycling impossible
        # but length must match first tuple, so empty result only if first is empty
        if len(first) == 0:
            return ()
        # Otherwise, cannot produce pairs, return tuple of pairs with None for second elements
        # Spec allows raise or return; here we return with None to maintain length
        return tuple((first[i], None) for i in range(len(first)))
    return tuple((first[i], second[i % len(second)]) for i in range(len(first)))



