def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    if all(ch == '9' for ch in s):
        # For all 9's, next palindrome is 10..01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd_length = (length % 2 != 0)
    mid = length // 2
    if odd_length:
        left = s[:mid+1]
    else:
        left = s[:mid]

    palindrome = make_palindrome(left, odd_length)
    if palindrome > n:
        return palindrome

    # Increment the middle part and then form palindrome again
    # Increment left as integer
    left_int = int(left)
    left_int += 1
    left_str = str(left_int)

    # If overflow in length after increment, means e.g. 999->1000 for left part
    if len(left_str) > len(left):
        # This implies length increased by 1, so palindrome length increases by 1 or 2
        # e.g. 999 -> 1001, or 9999->10001
        # For odd length, length increases by 1
        # For even length, length increases by 1 also because palindrome grows
        # So just return 10..01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')
    else:
        return make_palindrome(left_str, odd_length)



