def find_solution(a, b, n):
    if b == 0:
        # Then equation is a*x = n; check if n divisible by a and x>=0
        if a == 0:
            return (0, 0) if n == 0 else "No solution"
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return "No solution"
    # Try x from 0 upwards to find (n - a*x) divisible by b
    x = 0
    while True:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            return (x, y)
        x += 1
        # To avoid infinite loop, since x grows unbounded, 
        # we can stop if sign pattern makes no sense.
        # But problem does not limit domain, so we rely on eventual solution or no solution.
        # However, if b != 0, eventually either solution found or no solution.
        # To avoid infinite loop, break when x > abs(b) + abs(n) + abs(a) for large bounds.
        # This is heuristic: if no solution within these bounds, no solution.
        if x > abs(b) + abs(n) + abs(a):
            break
    return "No solution"



