def smallest_missing(arr, left, right):
    if left > right:
        return 0
    # Skip negatives on the left
    while left <= right and arr[left] < 0:
        left += 1
    if left > right:
        return 0
    # Binary search for smallest missing non-negative integer
    low, high = left, right
    while low <= high:
        mid = (low + high) // 2
        # Expected value if no missing is mid - left
        if arr[mid] == mid - left:
            low = mid + 1
        elif arr[mid] > mid - left:
            high = mid - 1
        else:
            # arr[mid] < mid - left due to duplicates or disorder, move low up
            low = mid + 1
    return low - left



