def find_Max(arr: list[int], low: int, high: int) -> int:
    if low == high:
        return arr[low]
    # If subarray is not rotated (sorted ascending), max is at high
    if arr[low] < arr[high]:
        return arr[high]
    while low < high:
        mid = (low + high) // 2
        # If mid element > next element, mid is max
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # If mid element < previous element, previous is max
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        # Decide which side to go
        if arr[mid] > arr[low]:
            low = mid + 1
        else:
            high = mid - 1
    return arr[low]



