def move_num(s: str, n) -> str:
    n_str = str(n)
    first_digit_index = None
    non_digits = []
    for i, c in enumerate(s):
        if c.isdigit():
            if first_digit_index is None:
                first_digit_index = i
        else:
            non_digits.append(c)
    if first_digit_index is None:
        # No digits found, append number at end
        return s + n_str
    # Insert n_str at first_digit_index in non_digits
    return ''.join(non_digits[:first_digit_index]) + n_str + ''.join(non_digits[first_digit_index:])



