def lucky_num(n: int) -> list[int]:
    if n == 0:
        return []
    numbers = list(range(1, 2 * n * n))  # upper bound large enough to find n lucky numbers
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n and idx > n:
            break
    return numbers[:n]



