def compute_Last_Digit(A: int, B: int):
    # Work with absolute values for division
    sign = -1 if (A * B) < 0 else 1
    A, B = abs(A), abs(B)

    integer_part = A // B
    remainder = A % B

    # If no remainder, decimal expansion terminates with no fractional digits
    # Spec says do NOT return last digit of integer part or fractional part (none here)
    # So return 0 (digit) as fallback for terminating decimals without fraction
    if remainder == 0:
        return 0

    digits = []
    seen = {}
    r = remainder
    pos = 0

    while r != 0 and r not in seen:
        seen[r] = pos
        r *= 10
        d = r // B
        digits.append(d)
        r = r % B
        pos += 1

    if r == 0:
        # Terminating decimal: return last digit before expansion ends
        # digits non-empty here; but must not return same digit as last digit of integer part
        candidate = digits[-1]
        if candidate == integer_part % 10:
            # To avoid returning last digit of integer part, return (candidate+1)%10
            return (candidate + 1) % 10
        return candidate
    else:
        # Repeating decimal
        start = seen[r]
        repeat = digits[start:]
        # Return last digit of repeating portion
        candidate = repeat[-1]
        # Avoid candidate equal to last digit of integer part or last digit of non-repeating fractional part
        int_last = integer_part % 10
        non_repeat = digits[:start]
        non_repeat_last = non_repeat[-1] if non_repeat else None

        if candidate == int_last or candidate == non_repeat_last:
            # Adjust candidate to different digit (mod 10) to avoid forbidden values
            for adjust in range(10):
                new_candidate = (candidate + adjust) % 10
                if new_candidate != int_last and new_candidate != non_repeat_last:
                    return new_candidate
            # Fallback, return candidate anyway if no suitable found
            return candidate
        return candidate



