def dif_Square(n: int) -> bool:
    if n % 4 == 2:
        return False
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b, then n = x*y with x,y integers of same parity (both even or both odd)
    # Also a = (x+y)//2, b = (y - x)//2 must be integers
    abs_n = abs(n)
    # Check all divisors of abs(n)
    # For zero, 0 = 0^2 - 0^2 trivially True
    if n == 0:
        return True
    # We try all factor pairs (x,y) with x*y = n and x,y same parity, such that a,b integers.
    # We only need to check x >= 1 (or positive divisors), and consider sign accordingly.
    # For negative n, factor pairs include negative divisors.
    import math

    # Get all divisor pairs of n (including negative)
    # To cover negative n, we factor abs(n), then assign signs to get product n
    # For each divisor d of abs_n, we have pairs (d, abs_n//d)
    # For n positive, (d, n//d) or (-d, -n//d) product positive
    # For n negative, (d, -abs_n//d) or (-d, abs_n//d)
    # So we generate all factor pairs with product n

    def factor_pairs(num):
        pairs = []
        limit = int(math.isqrt(num))
        for i in range(1, limit + 1):
            if num % i == 0:
                pairs.append((i, num // i))
        return pairs

    abs_pairs = factor_pairs(abs_n)
    candidates = []
    if n > 0:
        # product positive: (d, n//d) and (-d, -n//d)
        for x, y in abs_pairs:
            candidates.append((x, y))
            candidates.append((-x, -y))
    else:
        # product negative: (d, -n//d) and (-d, n//d)
        for x, y in abs_pairs:
            candidates.append((x, -y))
            candidates.append((-x, y))

    for x, y in candidates:
        if (x + y) % 2 == 0 and (y - x) % 2 == 0:
            a = (x + y) // 2
            b = (y - x) // 2
            # a,b integers by construction, check if a^2 - b^2 == n
            if a * a - b * b == n:
                return True
    return False



