def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if all(ch == '9' for ch in s):
        # If all 9s, next palindrome is 10..01 with length+1
        return int('1' + ('0' * (length - 1)) + '1')
    # Generate palindrome by mirroring left to right
    half = (length + 1) // 2
    left = s[:half]
    if length % 2 == 0:
        pal = left + left[::-1]
    else:
        pal = left + left[:-1][::-1]
    pal_num = int(pal)
    if pal_num > num:
        return pal_num
    # Increment the left half and mirror again
    left_num = int(left) + 1
    left_str = str(left_num)
    # If incrementing left changes length (e.g. 999 + 1 = 1000)
    if len(left_str) > len(left):
        # For even length, now length increases by 1, so palindrome is 10..01 with length+1
        # For odd length, same logic applies
        return int('1' + ('0' * (length - 1)) + '1')
    if length % 2 == 0:
        pal = left_str + left_str[::-1]
    else:
        pal = left_str + left_str[:-1][::-1]
    return int(pal)



