def find_solution(a: int, b: int, n: int):
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return "No solution"
    x = 0
    # To avoid infinite loop in case no solution, set a reasonable upper bound:
    # If a != 0, max_x = n//a if a>0 else max(0, n//a), else large number if a==0
    # But since we must scan from 0 upwards, we just keep going until no solution found or until no more x can satisfy rhs >= 0
    while True:
        rhs = n - a * x
        # For b == 0 special case
        if b == 0:
            if rhs == 0 and x >= 0:
                y = 0
                if y >= 0:
                    return (x, y)
            # If rhs < 0 and b=0, no solution for higher x either if a>0 or a<0? 
            # We continue scanning x as per spec until no solution found.
        else:
            if rhs % b == 0:
                y = rhs // b
                if x >= 0 and y >= 0:
                    return (x, y)
            # If rhs < 0 and b > 0, no solution for larger x either if a positive? But we must scan anyway.
        # Termination condition: When increasing x makes rhs too small for any y >= 0
        # If b > 0 and rhs < 0 no point in continuing
        if b > 0 and rhs < 0:
            break
        # If b < 0 and rhs < 0, maybe y negative to satisfy, so continue
        # But if b < 0 and rhs < 0, y = rhs/b positive if rhs and b negative
        # So no general rule, so we continue indefinitely but to avoid infinite loop:
        # Limit search to some large number (e.g. 10**6)
        if x > 10**6:
            break
        x += 1
    return "No solution"



