def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return m if m >= 1 else 0
    # If m < 2^(n-1), no sequences possible due to doubling condition
    if m < 2 ** (n - 1):
        return 0
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(pos: int, prev: int) -> int:
        if pos == n:
            return 1
        total = 0
        start = max(prev, 2 * prev) if pos > 0 else 1
        # Actually, for pos==0, prev is meaningless, we start from 1 to m.
        # For pos > 0, current element >= 2*prev and >= prev (nondecreasing),
        # so current element >= 2*prev (2*prev >= prev always).
        # So lower bound is 2*prev.
        if pos == 0:
            start = 1
        else:
            start = max(prev, 2 * prev)
        for val in range(start, m + 1):
            total += count_sequences(pos + 1, val)
        return total

    return count_sequences(0, 0)



