def sum_Of_product(n: int) -> int:
    """
    Calculate the sum of the products of consecutive binomial coefficients for a given integer n.

    Specifically, compute the sum:
        sum_{i=0}^{n-1} (C(n, i) * C(n, i+1))

    where C(n, k) is the binomial coefficient "n choose k".

    Parameters:
    ----------
    n : int
        The upper limit of the summation and the parameter for the binomial coefficients.

    Returns:
    -------
    int
        The computed sum of the products of consecutive binomial coefficients.

    Examples:
    --------
    >>> sum_Of_product(1)
    1
    >>> sum_Of_product(2)
    4
    >>> sum_Of_product(3)
    15
    """
    from math import comb
    return sum(comb(n, i) * comb(n, i + 1) for i in range(n))



