from typing import List

def lucky_num(n: int) -> List[int]:
    lucky = list(range(1, 2 * n * n))  # start with a large enough list of natural numbers
    idx = 1
    while idx < len(lucky):
        step = lucky[idx]
        if step > len(lucky):
            break
        lucky = [num for i, num in enumerate(lucky) if (i + 1) % step != 0]
        idx += 1
        if len(lucky) >= n and idx >= n:
            # Optimization: if we have enough numbers and processed enough steps, break early
            break
    return lucky[:n]



