def compute_Last_Digit(a: int, b: int) -> int:
    if a > b or a < 0 or b < 0:
        return 0
    # The quotient factorial(b)/factorial(a) = product of integers from a+1 to b inclusive
    # If a == b, quotient is 1
    if a == b:
        return 1
    # Compute product of range a+1 to b modulo 10 to get last digit
    product = 1
    for x in range(a + 1, b + 1):
        product *= x
        product %= 10
    # Since product is integer, division is exact by definition here
    return product



