def dif_Square(value: int) -> bool:
    # Based on the identity: a² - b² = (a+b)(a-b)
    # For integers a,b, value can be represented as difference of squares iff
    # value can be expressed as product of two integers x and y with same parity:
    # x = a+b, y = a-b and both x,y have same parity (both even or both odd).
    # Because a = (x+y)//2, b = (x-y)//2 must be integers.
    n = value
    # Iterate over divisors of n (including negative ones)
    # To cover all integer pairs (x,y) with x*y = n
    # For zero, 0=0²-0², so True
    if n == 0:
        return True
    abs_n = abs(n)
    from math import isqrt
    for i in range(1, isqrt(abs_n) + 1):
        if abs_n % i == 0:
            d1, d2 = i, abs_n // i
            # Check pairs (d1, d2) and (-d1, -d2), (d1, -d2), (-d1, d2) to cover sign combos
            for x, y in [(d1, d2), (-d1, -d2), (d1, -d2), (-d1, d2)]:
