def next_smallest_palindrome(n: int) -> int:
    def is_all_nines(s: str) -> bool:
        return all(ch == '9' for ch in s)

    s = str(n)
    length = len(s)

    # Special case: all 9's, e.g. 9 -> 11, 99 -> 101, 999 -> 1001
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Generate palindrome by mirroring left half to right
    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            palindrome = left + left[:-1][::-1]
        else:
            palindrome = left + left[::-1]
        return int(palindrome)

    odd_length = (length % 2 != 0)
    left_half_len = (length + 1) // 2
    left_half = s[:left_half_len]

    palindrome = make_palindrome(left_half, odd_length)

    if palindrome > n:
        return palindrome

    # Increment the middle part and mirror again
    # Increment left_half as integer
    left_num = int(left_half)
    left_num += 1
    left_half = str(left_num)

    # If incrementing left_half changes its length (e.g. 999 -> 1000)
    if len(left_half) > left_half_len:
        # This means palindrome length increases by 1 or 2 digits
        # For example, 999 -> 1000 means next palindrome is 10001 (length +1)
        # We handle this by returning palindrome of length+1 with 1 followed by zeros then 1
        return int('1' + ('0' * (length - 1)) + '1')
    else:
        palindrome = make_palindrome(left_half, odd_length)
        return palindrome



