def sort_sublists(coll):
    out_type = type(coll)
    result = []
    for subseq in coll:
        subseq_type = type(subseq)
        sorted_subseq = sorted(subseq)
        if subseq_type is tuple:
            sorted_subseq = tuple(sorted_subseq)
        elif subseq_type is list:
            sorted_subseq = list(sorted_subseq)
        else:
            # Preserve the original subsequence type if not list or tuple
            # by reconstructing with its type if possible, else fallback to list
            try:
                sorted_subseq = subseq_type(sorted_subseq)
            except Exception:
                sorted_subseq = list(sorted_subseq)
        result.append(sorted_subseq)
    if out_type is tuple:
        return tuple(result)
    elif out_type is list:
        return result
    else:
        # Preserve input collection type if not list or tuple, try reconstruct
        try:
            return out_type(result)
        except Exception:
            return result



