def find_solution(a: int, b: int, n: int) -> tuple[int, int] | None:
    if a == 0 and b == 0:
        # Equation 0*x + 0*y = n
        # Solution exists only if n == 0; minimal x=0, y=0
        if n == 0:
            return (0, 0)
        else:
            return None
    if b == 0:
        # Equation a*x = n
        # x must be integer and non-negative; y arbitrary integer (choose y=0)
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return None
    if a == 0:
        # Equation b*y = n
        # x=0 minimal non-negative x always
        if n % b == 0:
            y = n // b
            return (0, y)
        else:
            return None
    # General case: a != 0 and b != 0
    x = 0
    while True:
        rem = n - a * x
        # Check if rem divisible by b
        if b != 0 and rem % b == 0:
            y = rem // b
            return (x, y)
        x += 1
        # To avoid infinite loop, stop if x becomes too large without solution.
        # Since no domain restrictions, but to be safe, break if x > abs(n)*2 + 1000
        # (heuristic upper bound to avoid infinite loops on no solution)
        if x > abs(n)*2 + 1000:
            break
    return None



