def get_total_number_of_sequences(N: int, K: int) -> int:
    if K == 0:
        return 0
    if K == 1:
        return max(0, N)
    if N < 1:
        return 0

    from functools import lru_cache

    @lru_cache(None)
    def dp(pos: int, prev: int) -> int:
        if pos == K:
            return 1
        total = 0
        start = 1 if prev == 0 else 2 * prev
        if start > N:
            return 0
        for val in range(start, N + 1):
            total += dp(pos + 1, val)
        return total

    return dp(0, 0)



