def text_match_two_three(string: str) -> bool:
    """
    Check if the input string contains the substring 'abb' or 'abbb'.

    Specifically, this function searches for the sequence where the first letter is 'a' 
    followed by exactly 2 or 3 repetitions of the letter 'b'.

    Parameters:
    - string (str): The string to be searched.

    Returns:
    - bool: True if 'abb' or 'abbb' appears anywhere in the string; False otherwise.
    """
    length = len(string)
    for i in range(length - 2):
        if string[i] == 'a':
            # Check for 'abb'
            if string[i+1:i+3] == 'bb':
                # Confirm not part of longer sequence 'abbb...'
                if i + 3 == length or string[i+3] != 'b':
                    return True
            # Check for 'abbb'
            if i + 3 < length and string[i+1:i+4] == 'bbb':
                # Confirm not part of longer sequence 'abbbb...'
                if i + 4 == length or string[i+4] != 'b':
                    return True
    return False



