def remove_column(collection, position):
    result = []
    for inner in collection:
        if len(inner) > position:
            # Remove element at position, preserve type
            if isinstance(inner, list):
                new_inner = inner[:position] + inner[position+1:]
            elif isinstance(inner, tuple):
                new_inner = inner[:position] + inner[position+1:]
                new_inner = tuple(new_inner)
            else:
                # For other sequence types, try to create a new instance of same type
                try:
                    new_inner = type(inner)(inner[:position] + inner[position+1:])
                except Exception:
                    # Fallback: convert to list
                    new_inner = list(inner[:position] + inner[position+1:])
            result.append(new_inner)
        else:
            # Inner grouping shorter than position, leave unchanged
            result.append(inner)
    # Preserve outer collection type if input is tuple
    if isinstance(collection, tuple):
        return tuple(result)
    return result



