from collections import Counter

def permute_string(s: str) -> list[str]:
    if not s:
        return ['']  # Only permutation of empty string

    counts = Counter(s)
    result = []
    path = []
    length = len(s)

    def backtrack():
        if len(path) == length:
            result.append(''.join(path))
            return
        for ch in counts:
            if counts[ch] > 0:
                counts[ch] -= 1
                path.append(ch)
                backtrack()
                path.pop()
                counts[ch] += 1

    backtrack()
    return result



