import re

def str_to_tuple(s: str) -> tuple[int, ...]:
    s = s.strip()
    if s and s[0] in '([' and s[-1] in ')]':
        s = s[1:-1].strip()
    # Split on commas or whitespace (any mix), treating them as delimiters
    parts = re.split(r'[,\s]+', s)
    # Filter out empty strings that may result from multiple spaces or commas
    parts = [p for p in parts if p]
    result = []
    for p in parts:
        # Parse as float first to handle floats like '1.0', then convert to int if exact
        f = float(p)
        i = int(f)
        if i != f:
            raise ValueError(f"Non-integer float value: {p}")
        result.append(i)
    return tuple(result)



