def capital_words_spaces(s: str) -> str:
    if not s:
        return s
    result = [s[0]]
    i = 1
    while i < len(s):
        c = s[i]
        prev = s[i - 1]
        # Detect transition from a capital word (possibly acronym) to another capital word:
        # Insert space if current char is uppercase and previous char is not space,
        # and also handle acronyms by not splitting every capital letter but grouping them.
        if c.isupper() and prev != ' ':
            # Check if we're inside a sequence of capitals (acronym):
            # If prev is uppercase, and next char exists and is uppercase, continue acronym.
            # Insert space only if next char is lowercase or None (end), meaning new word.
            next_char = s[i + 1] if i + 1 < len(s) else None
            if prev.islower():
                # Previous lowercase followed by uppercase => split
                result.append(' ')
            elif prev.isupper():
                # Previous uppercase followed by uppercase:
                # If next_char is None or lowercase, insert space before current capital letter
                # else continue acronym (no space)
                if next_char is None or (next_char.islower() or next_char == ' '):
                    result.append(' ')
                # else no space, continue acronym
            else:
                # prev not letter (digit/punct), just insert space
                result.append(' ')
        result.append(c)
        i += 1
