def Odd_Length_Sum(group):
    """
    Given a list of numbers called group, return the sum of all elements from every contiguous sublist of group that has an odd length.

    Specifically, consider every contiguous sublist (slice) of group whose length is odd (1, 3, 5, ...). Sum all the numbers contained in all such sublists, and return that total sum.

    Parameters:
    group (list of numbers): The input list of numbers.

    Returns:
    number: The total sum of elements from all odd-length contiguous sublists of group.
    """
    total = 0
    n = len(group)
    for start in range(n):
        for length in range(1, n - start + 1, 2):  # odd lengths only
            total += sum(group[start:start+length])
    return total



