def lucky_num(n: int) -> list[int]:
    if n == 0:
        return []
    # Start with the list of odd numbers, since lucky numbers are generated by sieving odds
    # We need enough numbers to sieve down to n lucky numbers.
    # An overestimate: generate roughly 3*n numbers initially, adjust if needed.
    limit = max(3*n, 10)
    while True:
        numbers = list(range(1, 2*limit, 2))  # odd numbers starting from 1
        idx = 1  # start sieving with second number in the list (index 1)
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            # Remove every step-th element starting from index step-1
            del numbers[step-1::step]
            idx += 1
        if len(numbers) >= n:
            return numbers[:n]
        limit *= 2



