def next_smallest_palindrome(n: int) -> int:
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # For inputs <= 1, no smaller palindrome exists; return a value < n (e.g. n-1)
    if n <= 1:
        return n - 1

    for candidate in range(n - 1, -1, -1):
        if is_palindrome(candidate):
            return candidate
    # If no palindrome found (theoretically impossible here), return n-1 as indicative
    return n - 1



