def find_solution(a: int, b: int, n: int):
    # Handle the trivial case where all are zero
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    # Handle cases where one coefficient is zero
    if a == 0:
        if b == 0:
            return None  # handled above, but for clarity
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Use extended Euclidean algorithm to find one solution to a*x + b*y = gcd(a,b)
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        else:
            g, s, t = extended_gcd(y, x % y)
            return (g, t, s - (x // y) * t)

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    # Check if n is divisible by gcd
    if n % g != 0:
        return None

    # Scale the solution to n
    x0 *= n // g
    y0 *= n // g

    # Adjust signs according to original a, b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # General solution:
    # x = x0 + k*(b/g)
    # y = y0 - k*(a/g)
    # We want x,y >= 0, find k integer satisfying both

    b_div_g = b // g
    a_div_g = a // g

    # To ensure x >= 0:
    # x0 + k*b_div_g >= 0 => k >= (-x0) / b_div_g if b_div_g > 0 else k <= (-x0)/b_div_g
    # To ensure y >= 0:
    # y0 - k*a_div_g >= 0 => k <= y0 / a_div_g if a_div_g > 0 else k >= y0 / a_div_g

    # Compute bounds for k
    candidates = []

    if b_div_g != 0:
        if b_div_g > 0:
            k_min_x = (-x0 + b_div_g - 1) // b_div_g  # ceil division
        else:
            k_min_x = (-x0) // b_div_g  # floor division because b_div_g < 0
    else:
        # b_div_g = 0 => no adjustment in x by k, so x0 must be >= 0
        if x0 < 0:
            return None
        k_min_x = None

    if a_div_g != 0:
        if a_div_g > 0:
            k_max_y = y0 // a_div_g  # floor division
        else:
            # a_div_g < 0
            k_max_y = (y0 + (-a_div_g) - 1) // a_div_g  # ceil division with negative divisor
    else:
        # a_div_g = 0 => no adjustment in y by k, so y0 must be >= 0
        if y0 < 0:
            return None
        k_max_y = None

    # Find k such that k >= k_min_x and k <= k_max_y
    # If any bound is None, that bound is unbounded

    # Normalize k_min_x and k_max_y for easier comparison
    if k_min_x is None:
        k_min_x = -10**18  # very small
    if k_max_y is None:
        k_max_y = 10**18   # very large

    if k_min_x > k_max_y:
        return None  # no k satisfies both

    # choose k = k_min_x (smallest k that satisfies x>=0)
    k = k_min_x

    x = x0 + k * b_div_g
    y = y0 - k * a_div_g

    if x < 0 or y < 0:
        # try k_max_y if different
        k = k_max_y
        x = x0 + k * b_div_g
        y = y0 - k * a_div_g
        if x < 0 or y < 0:
            return None

    return (x, y)



