def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 1:
        return m
    dp = [0] + [1] * m  # dp[val] = count of sequences of length 1 starting with val
    for _ in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # Precompute prefix sums to efficiently sum dp over intervals
        prefix = [0] * (m + 2)
        for val in range(1, m + 1):
            prefix[val] = prefix[val - 1] + dp[val]
        for val in range(1, m + 1):
            lower = val * 2
            if lower <= m:
                new_dp[val] = prefix[m] - prefix[lower - 1]
            else:
                new_dp[val] = 0
        dp = new_dp
    return sum(dp[1:])



