def dict_depth(d: dict) -> int:
    """
    Calculate the depth of a dictionary `d`, where the depth is defined as the maximum number of nested dictionaries along any path within `d`.

    Only nested dictionaries contribute to the depth. Other container types such as lists, tuples, or sets do not increase the depth even if they contain dictionaries.

    The depth of an empty dictionary or a dictionary with no nested dictionaries is 1.

    Examples:
    >>> dict_depth({})
    1
    >>> dict_depth({'a': 1})
    1
    >>> dict_depth({'a': {'b': 2}})
    2
    >>> dict_depth({'a': [1, {'b': 2}]})
    2
    >>> dict_depth({'a': {'b': {'c': 3}}, 'd': 4})
    3
    """
    def depth_in_list(lst):
        max_depth = 0
        for item in lst:
            if isinstance(item, dict):
                max_depth = max(max_depth, dict_depth(item))
            elif isinstance(item, list):
                max_depth = max(max_depth, depth_in_list(item))
        return max_depth

    max_child_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            max_child_depth = max(max_child_depth, dict_depth(v))
        elif isinstance(v, list):
            max_child_depth = max(max_child_depth, depth_in_list(v))
    return 1 + max_child_depth



