def smallest_missing(array, start, end):
    s = set(array)
    n = len(array)
    if n == 0:
        return 0
    # Start searching from the smallest element in array or 0, whichever is smaller
    # Because missing could be smaller than array[start], also could be negative
    # We'll search from min(array[0], 0) upwards for missing positive or zero
    # And also check negatives below min(array)
    min_val = array[0]
    # Check missing integers below min_val by scanning downwards from min_val - 1
    # but to find smallest missing integer in all integers (including negatives),
    # it's easier to scan from min_val downwards to min_val - (len(array)+1)
    # but since integers are infinite, we just check negatives down to min_val - len(array) -1
    # to cover missing negatives
    for x in range(min_val - 1, min_val - len(array) - 2, -1):
        if x not in s:
            return x
    # Now check starting from 0 upwards (or min_val if min_val<0) for missing integers
    start_search = min(0, min_val)
    x = start_search
    # Scan upwards until we find a missing integer
    while True:
        if x not in s:
            return x
        x += 1



