from typing import List

def find_Max(array: List[int], low: int, high: int) -> int:
    # If subarray is not rotated (sorted ascending), max is at high
    if array[low] <= array[high]:
        return array[high]

    while low < high:
        mid = (low + high) // 2
        # If mid element is greater than next element, mid is max
        if mid < high and array[mid] > array[mid + 1]:
            return array[mid]
        # If mid element is smaller than previous element, previous is max
        if mid > low and array[mid] < array[mid - 1]:
            return array[mid - 1]
        # Decide which side to go
        if array[mid] >= array[low]:
            low = mid + 1
        else:
            high = mid - 1
    return array[low]



