def move_num(s: str, num: str) -> str:
    if not num or len(num) > len(s):
        return s
    parts = []
    i = 0
    while i < len(s):
        if s.startswith(num, i):
            parts.append(num)
            i += len(num)
        else:
            parts.append(s[i])
            i += 1
    moved = [p for p in parts if p == num]
    remained = [p for p in parts if p != num]
    return ''.join(remained) + ''.join(moved)



