def str_to_tuple(s: str) -> tuple[int, ...]:
    if s == "":
        return ()
    parts = s.split(", ")
    if any("," in part or part.strip() != part for part in parts):
        # This catches cases where spaces are misplaced or extra spaces exist inside parts
        # but since split is on ", " exactly, just checking for ',' inside parts detects invalid separators
        # and strip check ensures no leading/trailing spaces inside parts
        raise ValueError("Invalid spacing or separator detected")
    try:
        return tuple(int(part) for part in parts)
    except ValueError as e:
        raise ValueError("Non-integer value encountered") from e



