def lucky_num(n: int) -> list[int]:
    if n == 0:
        return []
    # Start with the list of natural numbers beginning with 1
    numbers = list(range(1, 2 * n * 10))  # over-allocate to ensure enough lucky numbers
    idx = 1  # index of the current lucky number in numbers list (0-based)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from index step-1 (0-based)
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            # If we already have at least n lucky numbers, can stop early
            break
    return numbers[:n]



