def get_noOfways(n: int) -> int:
    """
    Calculate the number of distinct ways to tile a 2 x n board using only 2 x 1 domino tiles.

    Parameters:
    n (int): The length of the board (the board has dimensions 2 rows by n columns).

    Returns:
    int: The total number of ways to completely cover the 2 x n board with 2 x 1 domino tiles without overlaps or gaps.
    """
    if n == 1:
        return 1
    elif n == 2:
        return 2
    a, b = 1, 2
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b



